import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        if line.strip():
            v, u = map(int, line.split())
            adj[v].append(u)
            adj[u].append(v)

    # Sort adjacency lists for more predictable DFS
    for i in range(1, n + 1):
        adj[i].sort()

    def find_path(u=None, visited=None, is_recovering=False):
        """Try to find a long path using DFS with path tracking."""
        if visited is None:
            visited = set()

        if u is None or u in visited:
            # Start from node with highest degree or node 1
            if u is None:
                start_node = 1
            else:
                start_node = u

            def dfs_long(curr, path, curr_visited):
                if len(curr_visited) >= n // k:
                    return path[:]

                neighbors = adj[curr]

                for nxt in neighbors:
                    if nxt not in curr_visited:
                        curr_visited.add(nxt)
                        result = dfs_long(nxt, path + [nxt], curr_visited)

                        # Check if this is sufficient
                        if result is not None and len(result) > n // k:
                            return result
                        if result is not None and len(result) >= n // k:
                            return result

                        curr_visited.remove(nxt)

                return None

            result = dfs_long(start_node, [start_node], {start_node})
            if result and len(result) >= n // k:
                return 'PATH\n' + str(len(result)) + '\n' + ' '.join(map(str, result))

        return None

    # First attempt: try finding a long path
    path_result = find_path()
    if path_result:
        return path_result

    # Strategy for finding cycles with representatives:
    # We need k cycles, each with length >= 3, not divisible by 3, 
    # and each having a unique representative vertex.

    cycles_found = []
    all_vertices = set(range(1, n + 1))
    used_vertices = set()

    def find_cycle_from(start):
        """Find a cycle containing start node."""
        path = [start]
        curr = adj[start][0] if adj[start] else None  # Try some neighbor

        if curr is None:
            return None

        if curr in path:
            # Found immediate cycle
            if len(path) >= 3 and len(path) % 3 != 0:
                return path
            return None

        def dfs_cycle(u, visited_set_in_cycle, actual_path):
            """DFS to find cycle back to start."""
            if u == start and len(actual_path) >= 3:
                if len(actual_path) % 3 != 0:
                    cycle = actual_path[:]
                    cycle.append(start)
                    return cycle

            for v in adj[u]:
                if v == start and actual_path[-1] != v:
                    if actual_path and len(actual_path) >= 3 and len(actual_path) % 3 != 0:
                        return actual_path[:]
                elif v not in visited_set_in_cycle:
                    visited_set_in_cycle.add(v)
                    path_with_v = actual_path + [v]
                    result = dfs_cycle(v, visited_set_in_cycle, path_with_v)
                    if result:
                        return result
                    visited_set_in_cycle.discard(v)

            return None

        visited_in_cycle = {start}
        cycle = dfs_cycle(start, visited_in_cycle, [start])
        return cycle if cycle and len(cycle) % 3 != 0 else None

    # Try to collect k cycles with unique representatives
    rep_count = [0] * (n + 1)

    def search_for_cycles():
        if len(cycles_found) >= k:
            return

        # Find cycles from unvisited vertices
        for start in range(1, n + 1):
            if start in used_vertices:
                continue

            cycle = find_cycle_from(start)
            if cycle is None:
                continue

            # Check if cycle length is valid
            if len(cycle) < 3 or len(cycle) % 3 == 0:
                cycle = cycle + []
                # Try to find a subcycle
                passed = cycle[:]
                while len(passed) >= 3 and passed[-1] != passed[0]:
                    passed.pop()

            if len(cycle) < 3 or len(cycle) % 3 == 0:
                continue

            # Mark some vertices from cycle as used
            for v in cycle:
                used_vertices.add(v)

            # Add cycle if we don't already have enough representatives
            cycles_found.append(cycle)
            rep_count[cycle[0]] += 1

        search_for_cycles()

    # Simpler greedy approach - find cycles and their representatives
    for _ in range(k):
        if len(cycles_found) >= k:
            break

        # Try to find cycle with a fresh representative
        for start in range(1, n + 1):
            if start not in used_vertices:
                cycle = find_cycle_from(start)

                if cycle and len(cycle) >= 3 and len(cycle[0]) % 3 != 0:
                    # Valid cycle found
                    used_vertices.update(cycle)
                    cycles_found.append(cycle)
                    break

    if len(cycles_found) >= k:
        cycles = cycles_found[:k]
        result = ['CYCLES']
        for cycle in cycles:
            result.append(str(len(cycle)))
            result.append(' '.join(map(str, cycle)))
        return '\n'.join(result)

    # If all options exhausted
    return '-1'


