from bisect import bisect_left

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    if idx >= len(lines):
        return ""

    q = int(lines[idx])
    idx += 1

    results = []

    for _ in range(q):
        if idx >= len(lines):
            break

        n = int(lines[idx])
        idx += 1

        if idx >= len(lines):
            break

        a = list(map(int, lines[idx].split()))
        idx += 1

        if n == 0:
            results.append("0")
            continue

        # Find distinct elements
        distinct = sorted(set(a))
        num_distinct = len(distinct)

        if num_distinct == 0:
            results.append("0")
            continue

        # Find first position of each distinct element
        first_pos = {}
        for i in range(n):
            if a[i] not in first_pos:
                first_pos[a[i]] = i

        # Get positions in sorted order of distinct elements
        positions = [first_pos[d] for d in distinct]

        # Find LIS of positions
        if len(positions) == 0:
            lis_len = 0
        else:
            # O(n log n) LIS algorithm
            tails = []
            for x in positions:
                pos = bisect_left(tails, x)
                if pos == len(tails):
                    tails.append(x)
                else:
                    tails[pos] = x
            lis_len = len(tails)

        # Answer: total distinct - max elements that can stay (LIS)
        ans = num_distinct - lis_len
        results.append(str(ans))

    return '\n'.join(results)

