class Solution:
    def __init__(self, input_str):
        self.input_str = input_str

    def get_initial_divisors(self, n):
        divisors = []
        for d in range(2, int(n**0.5) + 1):
            if n % d == 0:
                divisors.append(d)
                if d * d != n:
                    divisors.append(n // d)
        divisors.append(n)
        divisors = sorted(set(divisors))
        return divisors

    def find_prime_factors(self, n):
        factors = []
        d = 2
        while d * d <= n:
            if n % d == 0:
                factors.append(d)
                while n % d == 0:
                    n //= d
            d += 1
        if n > 1:
            factors.append(n)
        return factors

    def get_all_prime_factors_for_divisors(self, divisors):
        prime_map = {}
        for d in divisors:
            if d == 1:
                prime_map[d] = []
                continue
            factors = self.find_prime_factors(d)
            prime_map[d] = factors
        return prime_map

    def try_get_valid_ordering(self, divisors, prime_map):
        n = len(divisors)
        if n <= 2:
            return divisors

        # Try grouping by prime factors
        sorted_by_first_prime = sorted(divisors, key=lambda x: (prime_map.get(x, [999])[0] if prime_map.get(x) else 999))

        # Try to build valid sequence greedily
        for start in range(len(sorted_by_first_prime)):
            index = start
            ordering = [sorted_by_first_prime[index]]
            visited = {sorted_by_first_prime[index]}

            while len(ordering) < n:
                current = ordering[-1]
                current_factors = prime_map.get(current, [999])

                candidates = [d for d in sorted_by_first_prime if d not in visited]

                best_idx = -1
                if not candidates:
                    break

                best_score = float('inf')

                for idx, val in enumerate(candidates):
                    if not candidates or idx < 0:
                        continue

                    score = 0
                    if current_factors and prime_map.get(val, []):
                        common = set(current_factors) & set(prime_map.get(val, []))
                        if not common:
                            score = 1000
                        else:
                            score = -len(common)

                    if score < best_score:
                        best_score = score
                        best_idx = idx

                if best_idx < 0 or best_idx >= len(candidates):
                    break

                best_val = candidates[best_idx]
                ordering.append(best_val)
                visited.add(best_val)

            # Check if valid
            valid = True
            for i in range(n):
                a = ordering[i]
                b = ordering[(i + 1) % n]
                if math.gcd(a, b) == 1:
                    valid = False
                    break

            if valid:
                return ordering

        # Fallback to sorted divisors
        return sorted(divisors)

