def solution(input_str):
    # Parse the input string
    input_str = input_str.strip()
    lines = input_str.split('\n')
    if not lines:
        return "-1\n"

    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i + 1 < len(lines):
            parts = lines[i].split()
            if len(parts) >= 2:
                u, v = int(parts[0]), int(parts[1])
                adj[u].append(v)
                adj[v].append(u)

    # Find connected components (their sizes)
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                size += 1
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(size)

    # Generate all lucky numbers up to n
    lucky = []
    def generate_lucky(current):
        if current > n or current == 0:
            return
        if current <= n:
            lucky.append(current)
        try:
            generate_lucky(current * 10 + 4)
            generate_lucky(current * 10 + 7)
        except RecursionError:
            pass

    generate_lucky(0)
    lucky.sort()

    # Remove duplicates and ensure 0 is not in lucky
    lucky = list(set(lucky))
    lucky = [x for x in lucky if x > 0 and x <= n]

    if not lucky:
        return "-1\n"

    # Use DP to find minimum components needed to form each lucky target
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0

    for comp in components:
        for v in range(n, comp - 1, -1):
            if dp[v - comp] != INF:
                dp[v] = min(dp[v], dp[v - comp] + 1)

    # Find minimum roads = (components needed - 1)
    ans = INF
    for target in lucky:
        if dp[target] != INF:
            roads = dp[target] - 1
            ans = min(ans, roads)

    if ans == INF:
        return "-1\n"
    else:
        return str(ans) + "\n"


