def solution(input_str):
    """
    Solve the Walrusland ticket problem.

    Find minimum x * y such that at least w lucky tickets exist.
    Constraints: 1 <= x <= maxx, 1 <= y <= maxy
    """
    try:
        parts = input_str.strip().split()
        if len(parts) < 3:
            return "-1"
        maxx, maxy, w = int(parts[0]), int(parts[1]), int(parts[2])
    except:
        return "-1"

    if w == 0:
        return "1 1"

    # Precompute lucky status for all possible (a, b) in range
    lucky = [[False] * (maxy + 1) for _ in range(maxx + 1)]
    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            lucky[a][b] = is_lucky(a, b)

    # Count total lucky tickets possible
    total_lucky = sum(sum(row) for row in lucky)
    if total_lucky < w:
        return "-1"

    # Try all pairs (x, y) and find minimum x*y with >= w lucky tickets
    min_prod = maxx * maxy + 1
    result = (1, maxy)  # Default fallback

    # Optimize: check smaller products first
    candidates = []
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            prod = x * y
            if candidates and prod > candidates[0][0]:
                break
            count = sum(1 for a in range(1, x + 1) for b in range(1, y + 1) if lucky[a][b])
            if count >= w:
                if prod < min_prod:
                    min_prod = prod
                    result = (x, y)
                elif prod == min_prod:
                    # Keep the one with smaller x
                    if x < result[0]:
                        result = (x, y)
                    elif x == result[0] and (len(candidates) == 0 or prod < candidates[0][0]):
                        pass
                candidates.append((prod, x, y))

    return f"{result[0]} {result[1]}"


