    # Parse input
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)

    # BFS from each node to compute distances
    def bfs(start, n, adj):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    # Compute all pairs shortest paths
    dist = [[bfs(i, n, adj) for i in range(1, n + 2)] for _ in range(n + 1)]

    # Precompute best prefixes and suffixes
    # best_prefix[j] = [i, max_dist] where dist(i,j) is maximized, i != j
    # best_suffix[k] = [l, max_dist] where dist(k,l) is maximized, l != k

    best_prefix = [[0, -1] for _ in range(n + 1)]
    for j in range(1, n + 1):
        for i in range(1, n + 1):
            if i == j:
                continue
            di_grad_j = dist[i][j]
            if di_grad_j != -1 and (best_prefix[j][1] < 0 or di_grad_j > best_prefix[j][1]):
                best_prefix[j] = [i, di_grad_j]

    best_suffix = [[0, -1] for _ in range(n + 1)]
    for k in range(1, n + 1):
        for l in range(1, n + 1):
            if l == k:
                continue
            dk_l = dist[k][l]
            if dk_l != -1 and (best_suffix[k][1] < 0 or dk_l > best_suffix[k][1]):
                best_suffix[k] = [l, dk_l]

    # Find best path with 4 nodes: i -> j -> k -> l
    best_score = -1
    best_result = [1, 2, 3, 4]

    for j in range(1, n + 1):
        for k in range(1, n + 1):
            if j == k:
                continue

            # Check if there's a valid path from j to k
            d_jk = dist[j][k]
            if d_jk == -1:
                continue

            # Get best i -> j
            best_i, best_ij = best_prefix[j]
            if best_i == 0:
                continue

            # Get best k -> l
            best_l, best_kl = best_suffix[k]
            if best_l == 0:
                continue

            # Ensure all 4 cities are distinct
            if best_i == j or best_i == k or best_l == j or best_l == k or best_i == best_l:
                continue

            total = best_ij + d_jk + best_kl
            if total > best_score:
                best_score = total
                best_result = [best_i, j, k, best_l]

    # Fallback if no 4 distinct cities found (shouldn't happen per problem statement)
    if best_score < 0:
        return "1 2 3 4"

    return ' '.join(map(str, best_result))

