def solution(input_str):
    """
    Solves Mr. Kitayuta's Garden problem using binary search.
    """
    # Parse input
    lines = input_str.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())
    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    def check(mid):
        """
        Check if it's possible to keep all bamboos at height <= mid.
        """
        total_hits = 0
        for h, a in bamboos:
            # Final height after m days without any hammering
            final_height = h + m * a
            if final_height > mid:
                # Calculate hammer hits needed to reduce to <= mid
                needed = (final_height - mid + p - 1) // p
                total_hits += needed
                # If we need more hits than available (k*m), this threshold is impossible
                if total_hits > k * m:
                    return False
        return True

    # Binary search for the minimum achievable maximum height
    lo, hi = 0, 10**18  # Sufficiently large upper bound
    while lo < hi:
        mid = (lo + hi) // 2
        if check(mid):
            hi = mid
        else:
            lo = mid + 1

    return str(lo)


