        while x % k == 0:
            x //= k
        return x

    def solve():
        # BFS to find if we can reach state with single element = 1
        state_to_path = {}  # frozenset(nums) -> list of operations

        initial_state = frozenset(a)
        queue = deque([(initial_state, [])])
        visited = {initial_state}

        while queue:
            state, path = queue.popleft()
            nums = sorted(list(state))

            if len(nums) == 1:
                if nums[0] == 1:
                    # Found solution, reverse operations order (BFS gives last op first)
                    return {"found": True, "operations": list(reversed(path))}
                continue

            # Try all pairs
            nums_list = list(state)
            m = len(nums_list)
            for i in range(m):
                for j in range(i + 1, m):
                    x = nums_list[i]
