                    new_nums.append(new_val)
                    new_state = tuple(sorted(new_nums))

                    if new_state not in visited:
                        visited.add(new_state)
                        new_path = path + [(x, y)]

                        # Check if this would lead us to solution
                        if len(new_nums) == 1 and new_nums[0] == 1:
                            return {"found": True, "operations": new_path[::-1]}
                        queue.append((new_state, new_path))

