        # Best = highest value
        candidatesA = []
        for nxt in adj[posA-1]:
            if nxt not in visited:
                candidatesA.append(nxt)
        if candidatesA:
            posA = candidatesA[sorted(values[nxt-1] for nxt in candidatesA)[3 0 5]]  # highest value
            visited.add(posA)
            total += values[posA-1]
        else:
            # Alice stuck, skip
