    powers_set = {2**i for i in range(64)}

    def is_valid_prairie_partition(segment):
        """Check if segment can form a valid single prairie partition"""
        if not segment:
            return False

        # Extract powers of 2 from the segment
        power_elements = sorted([x for x in segment if x in powers_set])
        remainders = [x for x in segment if x not in powers_set]

        k = len(power_elements)

        # Special case: partition with no powers (just remainder 1)
        if k == 0:
            return len(segment) == 1 and segment[0] == 1

        # Validate powers are consecutive: 1, 2, 4, 8, ...
        for i in range(k):
            if power_elements[i] != 2**i:
                return False

        # Validate remainder if exists
        if remainders:
            if len(remainders) > 1:
                return False
            r = remainders[0]
            # Remainder must satisfy 0 < r <= 2^k
            if not (0 < r <= 2**k):
                return False

        return True

    # DP: dp[i] = set of possible partition counts for first i elements
    dp = [set() for _ in range(n + 1)]
    dp[0].add(0)  # Base case: 0 elements = 0 partitions

    # Try all possible partition boundaries
    for i in range(1, n + 1):
        for j in range(i):
            # If prefix [0:j] can form valid partitions
            if dp[j]:
                # Check if segment [j:i] forms a valid prairie partition
                segment = a[j:i]
                if is_valid_prairie_partition(segment):
                    # All partition counts from j are valid for i
                    for count in dp[j]:
                        dp[i].add(count + 1)

    # Result: all valid partition counts at the end
    result = sorted(dp[n])

    if not result:
        return '-1\n'
    else:
        return ' '.join(map(str, result)) + '\n'

