    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    MOD = 10**9 + 7

    if n == 0:
        return "1"

    # Square-free part
    def get_sf(x):
        res = x
        i = 2
        while i * i <= res:
            while res % (i*i) == 0:
                res //= (i*i)
            i += 1
        return res

    # Count by square-free part
    groups = {}
    for x in a:
        sf = get_sf(x)
        groups[sf] = groups.get(sf, 0) + 1

    sizes = sorted(groups.values())

    if n == 1:
        return "1"

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i-1] * i) % MOD

    inv = [1] * (n + 1)
    inv[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv[i] = (inv[i+1] * (i+1)) % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv[k] % MOD * inv[n-k] % MOD

    def P(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv[k] % MOD * inv[n-k] % MOD

    dp = [0] * (n + 1)
    dp[0] = 1
    total = 0

    for sz in sizes:
        ndp = [0] * (n + 1)
        for bad in range(total + 1):
            if dp[bad] == 0:
                continue

            slots = total + 1  # positions to place

            for k in range(sz - 1):
                sign = 1 if k % 2 == 0 else -1
                ways = C(sz, k + 1)
                pos = P(slots * 2, sz) % MOD

                cont = dp[bad] * ways % MOD * pos % MOD
                if sign == -1:
                    cont = (MOD - cont) % MOD

                ndp[bad + k] = (ndp[bad + k] + cont) % MOD

        dp = ndp
        total += sz

    ans = 0
    for bad in range(total + 1):
        if bad % 2 == 0:
            ans = (ans + dp[bad]) % MOD
        else:
            ans = (ans - dp[bad] + MOD) % MOD

    return str(ans)

