def solve_single(n):
    if n <= 0:
        return 0

    # Generate Fibonacci numbers up to n
    fibs = [1, 2]
    while fibs[-1] <= n:
        fibs.append(fibs[-1] + fibs[-2])

    # dp[i][j] = number of ways to get sum 'i' using first 'j' Fibonacci numbers
    # We'll use a rolling dict approach for space efficiency

    dp = {0: 1}  # 0 can be formed in 1 way (empty set)

    for f in fibs:
        if f > n:
            break
        # Create new states by adding f to existing sums
        new_dp = dp.copy()
        for old_sum, count in dp.items():
            new_sum = old_sum + f
            if new_sum <= n:
                new_dp[new_sum] = new_dp.get(new_sum, 0) + count
        dp = new_dp

    return dp.get(n, 0)

