import sys
from math import gcd

MOD = 998244353

def power(a, b, m):
    result = 1
    a %= m
    while b > 0:
        if b & 1:
            result = result * a % m
        a = a * a % m
        b >>= 1
    return result

def inv(n, m):
    return power(n, m - 2, m)

def factorize(n):
    """Fast factorization using trial division up to sqrt(n)"""
    factors = {}
    d = 2
    temp = n
    # Trial division
    while d * d <= temp:
        if temp % d == 0:
            while temp % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp //= d
        if d == 2:
            d = 3
        else:
            d += 2
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def nCr_dot(n, r):
    """n! / r! modulo MOD (falling factorial)"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    result = 1
    for i in range(r):
        result = result * (n - i) % MOD
    return result

def solve(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    D = int(lines[0])
    q = int(lines[1])

    results = []
    for i in range(2, 2 + q):
        parts = lines[i].split()
        v = int(parts[0])
        u = int(parts[1])

        if v == u:
            results.append('1')
            continue

        # Factorize v and u
        vf = factorize(v)
        uf = factorize(u)

        # For each prime, calculate descent and ascent needed
        # Path goes from v to gcd(v,u) then to u
        dp = 0  # total descent steps
        up = 0  # total ascent steps

        all_primes = set(vf.keys()) | set(uf.keys())
        for p in all_primes:
            vp = vf.get(p, 0)
            up_p = uf.get(p, 0)
            if vp < up_p:
                up += up_p - vp  # need to ascend
            elif vp > up_p:
                dp += vp - up_p  # need to descend

        # The answer is dot product C(dp + up, dp)
        ans = nCr_dot(dp + up, dp)
        results.append(str(ans))

    return '\n'.join(results)

